/* COHEN-SUTHERLAND 2D LINE CLIPPING */
#include<stdio.h>
#include<graphics.h>
int i,, xwmin, xwmax, ywmin, ywmax;
int x1, y1, x2, y2, code1[4], code2[4], flag, flag1;
int newx1, newx2, newy1, newy2;
void inter();
int reject();
void main()
{
int gd = DETECT, gm;
initgraph(&gd, &gm,"");
printf("Enter the window coordinates\n");
scanf("%d %d %d %d", &xwmin, &ywmin, &xwmax, &ywmax);
printf("enter the line coordinates\n");
scanf("%d %d %d %d", &x1, &y1, &x2, &y2);
printf("Before clipping\n");
setcolor(RED);
rectangle(xwmin, ywmin, xwmax, ywmax);
line(x1, y1, x2, y2);
if(x1 < xwmin)code1[0] = 1;
if(x1 > xwmax)code1[1] = 1;
if(y1 < ywmin)code1[2] = 1;
if(y1 > ywmax)code1[3] = 1;
if(x2 < xwmin)code2[0] = 1;
if(x2 > xwmax)code2[1] = 1;
if(y2 < ywmin)code2[2] = 1;
if(y2 > ywmax)code2[3] = 1;
getch();
clrscr();
printf("After clipping\n");
setcolor(BLUE);
rectangle(xwmin, ywmin, xwmax, ywmax);
flag = accept();
if(flag = = 1)
{
setcolor(BLUE);
line(x1, y1, x2, y2);
}
else flag1 = reject();
if(flag1 = = 1)
{
return;
}
else
{
inter();
newx1 = x1;
newy1 = y1;
newx2 = x2;
newy2 = y2;
printf("%d %d %d %d", newx1, newy1, newx2, newy2);
line(newx1, newy1, newx2, newy2);
}
getch();
}
int accept()
{
for(i = 0; i < 4; i++)
{
if(code1[i] = = 0 && code2[i]==0)
flag = 1;
}
flag = 0;
return(flag);
}
int reject()
{
for(i = 0; i < 4; i++)
{
if(code1[i] ! = 0 && code2[i] ! = 0)
flag 1 = 1;
}
flag 1 = 0;
return(flag 1);
}
void inter()
{
m = (y2 − y1)/(x2 − x1);
if(code1[0] = = 1)
{
y1 = y1 + (xwmin − x1)*m;
x1 = xwmin;
}
if(code1[1] = = 1)
{
y1 = y1 + (xwmax − x1)*m;
x1 = xwmax;
}
if(code1[2] = = 1)
{
x1 = x1 + ((ywmin − y1)/m);
y1 = ywmin;
}
if(code1[3] = = 1)
{
x1 = x1 + ((ywmax − y1)/m);
y1 = ywmax;
}
if(code2[0] = = 1)
{
y2 = y2 + (xwmin − x2)*m;
x2 = xwmin;
}
if(code2[1]==1)
{
